/**
 * The planner primitives against vectors generated by the vendored Python
 * (see test/helpers/plannerVectors.ts for the generator). Set
 * PLANNER_VECTORS_JSON to a generator output file to run a larger sweep.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { solve } from "../server/driver/motion/cubicEqn.ts";
import {
  calcJerk,
  scurveJerk,
  scurveJerk2,
  scurvePlan,
  scurveTime,
  striangle,
  t3SegData,
  tdSegData,
} from "../server/driver/motion/planUtils.ts";
import { isComplex } from "../server/driver/motion/pyMath.ts";
import {
  computeSegment,
  trajectory,
  type PenPosition,
  type PlannerContext,
  type SegmentTarget,
  type T3Params,
  type TDParams,
} from "../server/driver/motion/index.ts";
import { plannerVectors } from "./helpers/plannerVectors.ts";

/* eslint-disable @typescript-eslint/no-explicit-any */
const V: any = process.env.PLANNER_VECTORS_JSON
  ? JSON.parse(readFileSync(process.env.PLANNER_VECTORS_JSON, "utf8"))
  : plannerVectors();

type Result = { ok: unknown } | { err: string };

function check(where: string, expected: Result, run: () => unknown): unknown {
  if ("err" in expected) {
    assert.throws(run, Error, `${where}: Python raised ${expected.err}`);
    return undefined;
  }
  const actual = run();
  assert.deepStrictEqual(actual, expected.ok, where);
  return actual;
}

// The planner only ever solves j*t^3 + 0*t^2 + 2|v|*t - d with j > 0, and
// those roots must match exactly. General coefficients reach code the
// planner cannot: b**2.0 and a**2.0 (macOS pow(x, 2) is not correctly
// rounded; V8 returns x*x) and, when h <= 0, acos/cos/sin (libm and V8
// disagree on ~17% of acos inputs). The root formulas cancel, so those get
// an error bound relative to the largest root; complex/real must still agree.
const GENERIC_REL_TOL = 1e-12;

test("cubic_eqn.solve", () => {
  let planner = 0;
  for (const [args, expected] of V.cubic) {
    const [a, b, c, d] = args as [number, number, number, number];
    if (!Array.isArray(expected)) {
      assert.throws(() => solve(a, b, c, d), Error, `solve(${args})`);
      continue;
    }
    const roots = solve(a, b, c, d).map((r) =>
      isComplex(r) ? { complex: true } : r
    );
    if (b === 0 && c >= 0 && a > 0) {
      planner++;
      assert.deepStrictEqual(roots, expected, `solve(${args})`);
      continue;
    }
    assert.equal(roots.length, expected.length, `solve(${args})`);
    const scale = Math.max(
      1,
      ...expected.map((r: unknown) => (typeof r === "number" ? Math.abs(r) : 0))
    );
    roots.forEach((r, i) => {
      const e = expected[i];
      if (typeof e !== "number") {
        assert.deepStrictEqual(r, e, `solve(${args}) root ${i}`);
        return;
      }
      assert.ok(
        typeof r === "number" && Math.abs(r - e) <= GENERIC_REL_TOL * scale,
        `solve(${args}) root ${i}: ${JSON.stringify(r)} vs ${e}`
      );
    });
  }
  assert.ok(planner > 0);
});

test("scurve_plan", () => {
  for (const [args, expected] of V.scurve_plan) {
    const [vIn, vMax, j, dist, minTime] = args;
    assert.deepStrictEqual(
      scurvePlan(vIn, vMax, j, dist, minTime),
      expected,
      `scurve_plan(${args})`
    );
  }
});

test("scurve_jerk and scurve_jerk2", () => {
  for (const [args, e1, e2] of V.scurve_jerk) {
    const [a, b, d, j] = args;
    assert.deepStrictEqual(scurveJerk(a, b, d, j), e1, `scurve_jerk(${args})`);
    assert.deepStrictEqual(
      scurveJerk2(a, b, d, j),
      e2,
      `scurve_jerk2(${args})`
    );
  }
});

test("scurve_time", () => {
  for (const [[a, b, j], expected] of V.scurve_time) {
    assert.equal(scurveTime(a, b, j), expected);
  }
});

test("striangle", () => {
  for (const [args, expected] of V.striangle) {
    const [vi, vf, vMax, j, d] = args;
    assert.equal(striangle(vi, vf, vMax, j, d), expected, `striangle(${args})`);
  }
});

test("calc_jerk", () => {
  for (const [[accel, jd, ju], expected] of V.calc_jerk) {
    const ref = {
      options: { accel },
      params: { jerk_pen_down: jd, jerk_pen_up: ju },
    };
    assert.deepStrictEqual(calcJerk(ref), expected);
  }
});

test("td_seg_data and t3_seg_data", () => {
  for (const [kind, params, before, stepScale, result, after] of V.seg_data) {
    const pos: PenPosition = { ...before };
    const actual =
      kind === "td"
        ? tdSegData(params as TDParams, pos, stepScale)
        : t3SegData(params as T3Params, pos, stepScale);
    assert.deepStrictEqual(actual, result, `${kind} ${params}`);
    assert.deepStrictEqual(pos, after, `${kind} ${params} position`);
  }
});

function context(c: any, phys: PenPosition, warnings: unknown[][]) {
  const ctx: PlannerContext = {
    options: { accel: c.accel },
    params: {
      resolution: c.resolution,
      const_speed: c.const_speed,
      bounds_tolerance: 0.003,
      jerk_pen_down: c.jerk_pen_down,
      jerk_pen_up: c.jerk_pen_up,
      model_name: "model",
    },
    bounds: [
      [-1e-9, -1e-9],
      [11.81 + 1e-9, 8.58 + 1e-9],
    ],
    step_scale: c.step_scale,
    speed_pendown: c.speed_pendown,
    speed_penup: c.speed_penup,
    pen: { phys },
    warnings: { add_new: (...args) => void warnings.push(args) },
  };
  return ctx;
}

test("compute_segment edge cases and sweep", () => {
  for (const v of V.compute_segment) {
    const warnings: unknown[][] = [];
    const pos: PenPosition = { ...v.start };
    const ctx = context(v.ctx, { ...v.start }, warnings);
    check(`compute_segment ${v.label}`, v.result, () =>
      computeSegment(ctx, v.in as SegmentTarget, pos)
    );
    assert.deepStrictEqual(pos, v.end, `${v.label} end`);
    assert.deepStrictEqual(warnings, v.warnings, `${v.label} warnings`);
  }
});

test("trajectory edge cases and sweep", () => {
  for (const v of V.trajectory) {
    const ctx = context(v.ctx, { ...v.start }, []);
    check(`trajectory ${v.label}`, v.result, () => trajectory(ctx, v.in));
    assert.deepStrictEqual(ctx.pen.phys, v.end, `${v.label} pen.phys`);
  }
});

test("labelled edge cases are present", () => {
  const labels = new Set(
    [...V.compute_segment, ...V.trajectory].map((v: any) => v.label)
  );
  for (const label of [
    "zero length",
    "below one step",
    "max speed in/out",
    "very short TD",
    "decel only",
    "180 corner",
    "trimmed to one segment (tuple quirk)",
  ]) {
    assert.ok(labels.has(label), label);
  }
});
